def designer_responsables_existants(apps, schema_editor):
    """Reprise : conserver la possibilité d'engager sa direction (changement A).

    Avant ce changement, tout audité affecté pouvait accepter un risque ou répondre au rapport
    provisoire au nom de sa direction. Désormais seul le « responsable de l'entité » le peut,
    et il y en a au plus un par direction et par mission. Règle de reprise, par couple
    (mission, direction du compte) des affectations d'audités actives :
    - une seule affectation : elle devient responsable (comportement inchangé) ;
    - plusieurs : la plus ancienne (created_at, puis id) devient responsable, les autres
      redeviennent de simples collaborateurs. Chaque direction garde ainsi un responsable
      (aucune direction ne perd la capacité d'agir) sans cumuler plusieurs responsables ; le
      RAI peut corriger ensuite depuis l'écran Équipe de la mission ;
    - compte sans direction : non traité (il ne pouvait déjà rien engager).
    Les affectations retirées (suppression logique) sont ignorées.
    """
    Affectation = apps.get_model("missions", "AffectationMission")
    retenues = {}
    lignes = (
        Affectation.objects.filter(role_mission="AUDITE", deleted_at__isnull=True)
        .exclude(utilisateur__direction_code="")
        .order_by("created_at", "id")
        .values_list("pk", "mission_id", "utilisateur__direction_code")
    )
    for pk, mission_id, direction in lignes:
        retenues.setdefault((mission_id, direction), pk)
    Affectation.objects.filter(pk__in=list(retenues.values())).update(responsable_entite=True)


